ALTER TABLE "climate_scenario_units" DROP CONSTRAINT "climate_scenario_identity";--> statement-breakpoint
ALTER TABLE "climate_scenario_units" ADD CONSTRAINT "climate_scenario_identity" CHECK ("climate_scenario_units"."experiment" in ('historical','ssp245','ssp585') AND "climate_scenario_units"."variable" in ('tasmin','tasmax','tas','pr') AND "climate_scenario_units"."year" between 1950 and 2100 AND "climate_scenario_units"."tile_latitude" between -60 and 89 AND "climate_scenario_units"."tile_longitude" between -180 and 179 AND "climate_scenario_units"."model" ~ '^[A-Za-z0-9][A-Za-z0-9_.-]{0,39}$');